import { AIChatAgent } from "@cloudflare/ai-chat";
import { streamText, convertToModelMessages, tool } from "ai";
import { createWorkersAI } from "workers-ai-provider";
import { z } from "zod";
import type { Env } from "./types";
import { D1_SCHEMA } from "./schema";

const SYSTEM_PROMPT = `あなたはデータ基盤のアシスタントです。
ユーザーの質問に対して、D1データベース (SQLite) に対するSQLを生成・実行して回答します。

## 利用可能なデータソース
- GitHub: コミット、リポジトリ、ユーザー情報
- Oura Ring: 睡眠、活動、コンディションデータ
- Linear: Issue、プロジェクト管理データ
- Withings: 体組成、睡眠、活動データ

## スキーマ
${D1_SCHEMA}

## ルール
- SELECT クエリのみ自動実行されます。データの変更は承認が必要です。
- 日本語で回答してください。
- 集計ビュー (v_ プレフィックス) が使える場合はそちらを優先してください。
- 大量データの取得は LIMIT を付けてください。
- 結果を簡潔にまとめて回答してください。
`;

export class DataAgent extends AIChatAgent<Env> {
  async onChatMessage(
    onFinish?: Parameters<AIChatAgent<Env>["onChatMessage"]>[0],
    options?: Parameters<AIChatAgent<Env>["onChatMessage"]>[1]
  ) {
    const workersai = createWorkersAI({ binding: this.env.AI });

    const result = streamText({
      model: workersai("@cf/meta/llama-3.3-70b-instruct-fp8-fast"),
      system: SYSTEM_PROMPT,
      messages: await convertToModelMessages(this.messages),
      abortSignal: options?.abortSignal,
      maxSteps: 5,
      tools: {
        queryD1: tool({
          description:
            "D1データベースに対してSQLクエリを実行する。SELECTクエリは自動実行、それ以外は承認が必要。",
          inputSchema: z.object({
            sql: z.string().describe("実行するSQLクエリ"),
            params: z.array(z.string()).optional().describe("バインドパラメータ"),
          }),
          needsApproval: async ({ sql }) => {
            const normalized = sql.trim().toUpperCase();
            return !normalized.startsWith("SELECT");
          },
          execute: async ({ sql, params }) => {
            try {
              const stmt = this.env.DB.prepare(sql);
              const bound = params?.length ? stmt.bind(...params) : stmt;
              const result = await bound.all();

              return {
                success: true,
                rowCount: result.results.length,
