import { tool } from "ai";
import { z } from "zod";
import { D1_SCHEMA } from "./schema";

export const SYSTEM_PROMPT = `あなたは Oura Ring データのアシスタントです。
ユーザーの質問に対して、D1データベース (SQLite) に対するSQLを生成・実行して回答します。

## 利用可能なデータ
Oura Ring から取得した健康データ（睡眠、活動、コンディション、心拍数）

## スキーマ
${D1_SCHEMA}

## ルール
- SELECT クエリのみ実行可能です。INSERT/UPDATE/DELETE は拒否してください。
- 日本語で回答してください。
- v_oura_daily_summary ビューが使える場合はそちらを優先してください。
- 大量データの取得は LIMIT を付けてください。
- 結果を簡潔にまとめて回答してください。
`;

function isSafeQuery(sql: string): boolean {
  const normalized = sql.trim().toUpperCase();
  return normalized.startsWith("SELECT") || normalized.startsWith("WITH");
}

export function createTools(db: D1Database) {
  return {
    queryD1: tool({
      description: "D1データベースに対してSELECTクエリを実行する。読み取り専用。",
      inputSchema: z.object({
        sql: z.string().describe("実行するSELECTクエリ"),
        params: z.array(z.string()).optional().describe("バインドパラメータ"),
      }),
      execute: async ({ sql, params }) => {
        if (!isSafeQuery(sql)) {
          return { success: false, error: "SELECT/WITH クエリのみ実行可能です。" };
        }
        try {
          const stmt = db.prepare(sql);
          const bound = params?.length ? stmt.bind(...params) : stmt;
          const queryResult = await bound.all();

          return {
            success: true,
            rowCount: queryResult.results.length,
            results: queryResult.results.slice(0, 50),
          };
        } catch (error) {
          return {
            success: false,
            error: error instanceof Error ? error.message : String(error),
          };
        }
      },
    }),
    listTables: tool({
      description: "D1データベースの全テーブルとビューの一覧を取得する",
      inputSchema: z.object({}),
      execute: async () => {
        const queryResult = await db
          .prepare(
            "SELECT name, type FROM sqlite_master WHERE type IN ('table', 'view') ORDER BY type, name"
          )
          .all();
        return queryResult.results;
      },
    }),
  };
}

